CREATE OR REPLACE FUNCTION check_series_name_uniformity(p_series_id bigint)
RETURNS boolean AS $$
BEGIN
    RETURN NOT EXISTS (
        SELECT 1 FROM core
        WHERE series_id = p_series_id
        GROUP BY series_id
        HAVING COUNT(DISTINCT canonical_name) > 1
    );
END;
$$ LANGUAGE plpgsql;

