CREATE OR REPLACE FUNCTION check_series_name_uniformity(p_content_key bigint)
RETURNS boolean AS $$
BEGIN
    RETURN NOT EXISTS (
        SELECT 1 FROM core c2
        WHERE c2.series_id = (SELECT series_id FROM core WHERE content_key = p_content_key)
        GROUP BY c2.series_id
        HAVING COUNT(DISTINCT c2.canonical_name) > 1
    );
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_series_name_uniformity()
RETURNS TABLE(series_id bigint, is_uniform boolean) AS $$
BEGIN
    RETURN QUERY
    SELECT c.series_id, COUNT(DISTINCT c.canonical_name) = 1 AS is_uniform
    FROM core c
    GROUP BY c.series_id;
END;
$$ LANGUAGE plpgsql;

