CREATE OR REPLACE FUNCTION check_series_name_uniformity(p_series_id bigint)
RETURNS boolean AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM core WHERE series_id = p_series_id) THEN
        RETURN FALSE;
    END IF;

    RETURN (SELECT COUNT(DISTINCT canonical_name) FROM core WHERE series_id = p_series_id) = 1;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_series_name_uniformity()
RETURNS SETOF core AS $$
BEGIN
    RETURN QUERY
    SELECT DISTINCT ON (c.series_id) c.*
    FROM core c
    ORDER BY c.series_id, c.canonical_name;
END;
$$ LANGUAGE plpgsql;

